export type NativeSettingsScope = "global" | "project";

export interface NativeSettingDefinition {
	path: string;
	category: "models" | "intelligence" | "agents" | "tools" | "safety" | "system";
	group: string;
	label: { en: string; ko: string };
	description: { en: string; ko: string };
	kind: "boolean" | "number" | "string" | "enum" | "array" | "object";
	defaultValue?: unknown;
	choices?: readonly string[];
	min?: number;
	max?: number;
	step?: number;
	integer?: boolean;
	items?: "string" | "number" | "object";
	recordValues?: "string" | "model-role" | "boolean-string" | "string-array" | "string-or-string-array" | "approval" | "json";
	secret?: boolean;
	admin?: boolean;
	confirmation?: boolean;
	scope: "global" | "both";
	appliesTo?: { en: string; ko: string };
}

export interface NativeSettingsSnapshot {
	path: string;
	scope: NativeSettingsScope;
	cwd?: string;
	settings: Record<string, unknown>;
	effectiveSettings: Record<string, unknown>;
	catalog: readonly NativeSettingDefinition[];
	secretStatus: Record<string, boolean>;
	issues?: readonly { path: string; message: string }[];
}

export interface NativeSettingsUpdate {
	settings?: Record<string, unknown>;
	scope?: NativeSettingsScope;
	cwd?: string;
	reset?: string[];
	secrets?: Record<string, string | null>;
	confirm?: string[];
}

